    \begin{equation} \label{eq_thm_bnd_case}
        \|\varphi-\widehat \varphi\| 
        % \le \frac{\| H\varphi-\langle H\varphi,\varphi \rangle \varphi \|}{\nu-2\|H\|}
        \leq \frac{\| H\varphi \|}{\nu-2\|H\|}.
    \end{equation}
